# Maybe 5s form paths between other colored regions

def analyze_paths(grid, connection_color):
    """Find connected components of connection_color"""
    rows, cols = len(grid), len(grid[0])

    # Build adjacency list of cells with connection_color
    adj = {}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == connection_color:
                neighbors = []
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == connection_color:
                        neighbors.append((nr, nc))
                if neighbors:
                    adj[(r,c)] = set(neighbors)

    return adj

