# Analyze color regions by shape properties
def analyze_color_regions(grid, color):
    rows, cols = len(grid), len(grid[0])
    visited = set()
    regions = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == color and (r,c) not in visited:
                # BFS to find all connected cells
                region = []
                queue = [(r,c)]
                visited.add((r,c))
                while queue:
                    cr, cc = queue.pop(0)
                    region.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))
                bbox_r = min(p[0] for p in region)
                bbox_c = min(p[1] for p in region)
                region_h = max(p[0] for p in region) - bbox_r + 1
                region_w = max(p[1] for p in region) - bbox_c + 1
                fill_ratio = len(region) / (region_h * region_w)
                regions.append({
                    'cells': region,
                    'size': len(region),
                    'bbox': (bbox_r, bbox_c, bbox_r+region_h-1, bbox_c+region_w-1),
                    'fill_ratio': fill_ratio,
                    'h': region_h,
                    'w': region_w
                })
    return regions

