def find_8connected_components(grid):
    """Find connected components using 8-way connectivity"""
    visited = set()
    results = []

    for r in range(15):
        for c in range(15):
            if grid[r][c] not in [0, 5] and (r,c) not in visited:
                color = grid[r][c]
                comp_cells = []
                queue = [(r, c)]

                while queue:
                    cr, cc = queue.pop(0)
                    if (cr, cc) not in visited:
                        visited.add((cr, cc))
                        comp_cells.append((cr, cc))

                        # Check 8 neighbors including diagonals
                        for dr in [-1, 0, 1]:
                            for dc in [-1, 0, 1]:
                                if dr == 0 and dc == 0:
                                    continue
                                nr, nc = cr+dr, cc+dc
                                if 0 <= nr < 15 and 0 <= nc < 15:
                                    if grid[nr][nc] == color and (nr, nc) not in visited:
                                        queue.append((nr, nc))

                min_r, max_r = min(p[0] for p in comp_cells), max(p[0] for p in comp_cells)
                min_c, max_c = min(p[1] for p in comp_cells), max(p[1] for p in comp_cells)
                bbox_area = (max_r - min_r + 1) * (max_c - min_c + 1)
                is_solid = len(comp_cells) == bbox_area

                results.append({
                    'color': color,
                    'size': len(comp_cells),
                    'bbox': (min_r, min_c, max_r, max_c),
                    'bbox_area': bbox_area,
                    'is_solid': is_solid
                })

    return results

